/* Tab-hidden: pause animations and kill transitions.
   IMPORTANT: avoid universal * selector � it forces full style recalc on every
   element when the class toggles, which can permanently degrade the compositor
   to ~12 FPS after alt-tab on boards with many elements. Target game-specific
   elements instead. */
html.fate-tab-hidden #s-game .bc,
html.fate-tab-hidden #s-game .hc,
html.fate-tab-hidden #s-game .cell,
html.fate-tab-hidden #s-game .zone,
html.fate-tab-hidden #s-game .zone-rows,
html.fate-tab-hidden #s-game .brow,
html.fate-tab-hidden #s-game .hand-strip,
html.fate-tab-hidden #s-game .actbar,
html.fate-tab-hidden #s-game .player-banner,
html.fate-tab-hidden #s-game .topbar,
html.fate-tab-hidden #s-game .zone-score-card,
html.fate-tab-hidden #s-game .zone-floating-banner,
html.fate-tab-hidden #s-game .opp-card-back,
html.fate-tab-hidden .cinematic-overlay,
html.fate-tab-hidden .consolidation-cinematic-overlay,
html.fate-tab-hidden .cc-overlay-v2,
html.fate-tab-hidden .placement-anim-ghost,
html.fate-tab-hidden .effect-activation-aura{
  animation-play-state:paused!important;
  transition-duration:0s!important;
}

/* Animations-off mode should be genuinely quiet. Keep functional targeting
   states visible, but stop the shared animated layers that still cost frames. */
html.fate-animations-off .screen.screen-fade-in,
html.fate-animations-off .screen.screen-fade-out,
html.fate-animations-off #s-game :is(.placement-anim-ghost,.placement-anim-card,.card-set-flash,.zone-take-flash,.effect-activation-aura,.last-turn-banner,.turn-timer-warning,.online-lag-spinner,.idle-glow-p1,.idle-glow-p2,.hand-sel-pulse,.tribute-card,.busser-zone-ready,.improvisor-ready),
html.fate-animations-off body :is(.draw-fly-card,.cinematic-subtitle-live,.booster-drop-banner),
html.fate-animations-off :is(.canvas-card-grid-sheen,.canvas-card-grid-sheen-sweep){
  animation:none!important;
  transition-duration:0s!important;
  filter:none!important;
  text-shadow:none!important;
  box-shadow:none!important;
  will-change:auto!important;
}

html.fate-animations-off #s-game #placement-anim-layer,
