/* --- End zone flash: longer animation --- */
html body #s-game .zone.final-zone-board-flash{
  animation:finalZoneBoardFlashLong .86s ease-out var(--final-zone-delay,0ms) both!important;
  z-index:35!important;
}
@keyframes finalZoneBoardFlashLong{
  0%{box-shadow:0 0 0 rgba(0,0,0,0),inset 0 0 0 1px rgba(255,246,191,.03);background-color:transparent;}
  10%{box-shadow:0 0 50px var(--final-zone-flash),inset 0 0 0 3px var(--final-zone-flash);background-color:var(--final-zone-fill);}
  50%{box-shadow:0 0 30px var(--final-zone-flash),inset 0 0 0 2px var(--final-zone-flash);background-color:var(--final-zone-fill);}
  80%{box-shadow:0 0 18px var(--final-zone-flash),inset 0 0 0 2px var(--final-zone-flash);background-color:var(--final-zone-fill);}
  100%{box-shadow:0 0 0 rgba(0,0,0,0),inset 0 0 0 1px rgba(255,246,191,.03);background-color:transparent;}
}

/* Override the short animation-duration rule from earlier in the cascade */
html body #s-game .final-zone-board-flash{
  animation-duration:.86s!important;
}

/* End reveal: possession should read as one zone flash at a time, without
   the redundant label window covering each zone. */
html body #s-game .zone.final-zone-board-flash::after{
  content:none!important;
  display:none!important;
}

