  --effect-flash-tint:rgba(210,174,82,.13);
  --effect-flash-inset:rgba(255,235,158,.1);
  --effect-flash-duration:3.5s;
  filter:none!important;
  opacity:1!important;
}
html body #s-game #board .bc.fate-effect-flash::before,
html body #s-game .bc.fate-effect-flash::before,
html body #s-game #board .bc.fate-effect-flash::after,
html body #s-game .bc.fate-effect-flash::after{
  content:''!important;
  display:block!important;
  position:absolute!important;
  pointer-events:none!important;
  box-sizing:border-box!important;
}
html body #s-game .bc.fate-effect-flash::before{
  inset:0!important;
  z-index:5!important;
  border-radius:inherit!important;
  background:var(--effect-flash-tint)!important;
  box-shadow:inset 0 0 20px var(--effect-flash-inset)!important;
}
html body #s-game .bc.fate-effect-flash::after{
  inset:auto!important;
  left:50%!important;
  top:50%!important;
  width:clamp(60px,88%,104px)!important;
  aspect-ratio:1!important;
  transform:translate(-50%,-50%)!important;
  z-index:6!important;
  border:0!important;
  border-radius:0!important;
  background:var(--effect-flash-color)!important;
  -webkit-mask:var(--effect-flash-mask) center/contain no-repeat!important;
  mask:var(--effect-flash-mask) center/contain no-repeat!important;
  filter:drop-shadow(0 2px 7px rgba(31,20,4,.7)) drop-shadow(0 0 12px var(--effect-flash-glow))!important;
