/* -------------------------------------------------------------------
   SIDE PANEL � SUSPENDED, LEFT, STYLISH
   Scoped under .fate-side-panel on #s-title. A floating panel on the
   LEFT with margin around it, decorative trim, section dividers,
   ornamental flourishes. Profile + daily challenges + compact chat.
   Remove the class to revert instantly.
   Toggle: localStorage.setItem('fate_side_panel','off') + refresh,
           or call window.toggleSidePanel().
   ------------------------------------------------------------------- */

/* --- Title screen: keep original centered layout � panel is overlaid --- */
#s-title.fate-side-panel{
  /* Don't change flex-direction � panel is absolutely positioned */
}

/* --- Suspended panel: floats on left with margin (NOT flush to edge) --- */
#fate-side-panel{
  display:none;
}
#s-title.fate-side-panel #fate-side-panel{
  display:flex!important;
  flex-direction:column!important;
  position:absolute!important;
  top:24px!important;
  left:80px!important;
  transform:none!important;
  width:280px!important;
  min-width:280px!important;
  max-width:280px!important;
  height:calc(100vh - 48px)!important;
  max-height:none!important;
  z-index:25!important;
  pointer-events:auto!important;

  /* Glass panel with multi-stop gradient */
  background:
    linear-gradient(180deg,
      rgba(12,10,6,.86) 0%,
      rgba(8,7,4,.92) 50%,
      rgba(12,10,6,.86) 100%)!important;

  /* Layered border + glow */
  border:1px solid rgba(201,168,76,.32)!important;
  border-radius:14px!important;
  box-shadow:
    0 18px 60px rgba(0,0,0,.6),
    0 0 36px rgba(201,168,76,.08),
    inset 0 1px 0 rgba(201,168,76,.12),
    inset 0 -1px 0 rgba(0,0,0,.4)!important;

  overflow:hidden!important;  /* corners cut content cleanly */
  animation:fate-sp-fadein .5s ease both!important;
}

@keyframes fate-sp-fadein{
  from{opacity:0;transform:translateX(-12px);}
  to{opacity:1;transform:translateX(0);}
}

/* --- Decorative corner ornaments (4 brackets) --- */
#s-title.fate-side-panel #fate-side-panel::before,
#s-title.fate-side-panel #fate-side-panel::after{
  content:''!important;
  position:absolute!important;
  width:18px!important;
  height:18px!important;
  pointer-events:none!important;
  z-index:2!important;
}
#s-title.fate-side-panel #fate-side-panel::before{
  top:8px;left:8px;
  border-top:1.5px solid rgba(232,196,82,.55);
  border-left:1.5px solid rgba(232,196,82,.55);
  border-top-left-radius:8px;
}
#s-title.fate-side-panel #fate-side-panel::after{
  bottom:8px;right:8px;
  border-bottom:1.5px solid rgba(232,196,82,.55);
  border-right:1.5px solid rgba(232,196,82,.55);
  border-bottom-right-radius:8px;
}

/* --- Inner container (no scrolling � content fits) --- */
#s-title.fate-side-panel .sp-inner{
  flex:1 1 auto!important;
  display:flex!important;
  flex-direction:column!important;
  overflow:hidden!important;
  scrollbar-width:none!important;
  padding:18px 14px!important;
  gap:14px!important;
}
#s-title.fate-side-panel .sp-inner::-webkit-scrollbar{width:5px;}
#s-title.fate-side-panel .sp-inner::-webkit-scrollbar-track{background:transparent;}
#s-title.fate-side-panel .sp-inner::-webkit-scrollbar-thumb{background:linear-gradient(180deg,rgba(232,196,82,.35),rgba(201,168,76,.15));border-radius:3px;}

/* --- Decorative section header / divider --- */
#s-title.fate-side-panel .sp-section-head{
  display:flex!important;
  align-items:center!important;
  gap:.5rem!important;
  margin:0 0 6px 2px!important;
  flex-shrink:0!important;
}
#s-title.fate-side-panel .sp-section-head::before,
#s-title.fate-side-panel .sp-section-head::after{
  content:''!important;
  flex:1!important;
  height:1px!important;
  background:linear-gradient(90deg,transparent,rgba(201,168,76,.35),transparent)!important;
}
#s-title.fate-side-panel .sp-section-head .sp-sh-glyph{
  font-size:.6rem!important;
  color:rgba(232,196,82,.7)!important;
  letter-spacing:.1em!important;
  font-family:'Cinzel',serif!important;
  text-transform:uppercase!important;
  white-space:nowrap!important;
  text-shadow:0 0 8px rgba(232,196,82,.25)!important;
}

/* --- Section card wrapper (shared by profile, daily, chat) --- */
#s-title.fate-side-panel .sp-section{
  position:relative!important;
  border:1px solid rgba(201,168,76,.14)!important;
  border-radius:9px!important;
  background:linear-gradient(160deg,rgba(255,255,255,.02),rgba(0,0,0,.18))!important;
