.mission-live-grid{
  display:flex;
  flex-direction:column;
  gap:.6rem;
}
.mission-live-card{
  border:1px solid rgba(201,168,76,.18);
  border-radius:9px;
  background:linear-gradient(160deg,rgba(201,168,76,.05),rgba(0,0,0,.3));
  padding:.7rem .9rem;
  cursor:pointer;
  transition:border-color .2s,box-shadow .2s,transform .15s;
}
.mission-live-card:hover{
  border-color:rgba(201,168,76,.45);
  box-shadow:0 0 18px rgba(201,168,76,.1);
  transform:translateY(-1px);
}
.mlc-players{
  display:flex;
  align-items:center;
  gap:.5rem;
}
.mlc-player{
  flex:1;
  min-width:0;
  display:flex;
  flex-direction:column;
  gap:.1rem;
}
.mlc-player-right{
  align-items:flex-end;
  text-align:right;
}
.mlc-name{
  font-family:'Cinzel',serif;
  font-size:.82rem;
  color:var(--text);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  font-weight:600;
}
.mlc-elo{
  font-size:.6rem;
  color:var(--dim);
}
.mlc-vs{
  font-family:'Cinzel',serif;
  font-size:.95rem;
  color:var(--gold);
  font-weight:700;
  letter-spacing:.1em;
  flex-shrink:0;
  padding:0 .3rem;
}
.mlc-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-top:.45rem;
  padding-top:.35rem;
  border-top:1px solid rgba(201,168,76,.08);
}
.mlc-spectators{
  font-size:.6rem;
  color:var(--dim);
  letter-spacing:.04em;
}
.mlc-action{
  font-family:'Cinzel',serif;
  font-size:.6rem;
  color:var(--gold);
  letter-spacing:.08em;
  opacity:.7;
  transition:opacity .2s;
}
.mission-live-card:hover .mlc-action{
  opacity:1;
}

/* === Title missions cleanup + title-window Mission Control === */
#s-title #daily-challenges-panel,
#s-title .daily-challenges-panel,
#s-title.fate-side-panel #daily-challenges-panel{
  display:none!important;
}

