#s-title .title-menu-stack > .title-btn:nth-of-type(8){
  grid-column:auto!important;
  justify-self:stretch!important;
  width:100%!important;
  margin-top:0!important;
}

#s-title.fate-menu-v2 #title-mission-control-btn,
#s-title.fate-menu-v2 #title-exit-game-btn{
  opacity:1!important;
