.mission-title-overlay[hidden]{
  display:none!important;
}

.mission-title-overlay{
  position:fixed;
  inset:0;
  z-index:26000;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:clamp(18px,3vw,46px);
  background:rgba(0,0,0,.58);
  backdrop-filter:blur(2px);
  will-change:opacity;
  animation:fadeIn .15s ease-out;
}

.mission-window{
  width:min(1060px,calc(100vw - 36px));
  max-height:min(780px,calc(100vh - 36px));
  display:flex;
  flex-direction:column;
  overflow:hidden;
  border:2px solid rgba(232,196,82,.62);
  border-radius:10px;
  background:
    linear-gradient(90deg,rgba(91,150,215,.12),transparent 28%,transparent 72%,rgba(210,70,64,.08)),
    linear-gradient(180deg,rgba(14,16,24,.96),rgba(5,6,10,.98));
  box-shadow:0 24px 70px rgba(0,0,0,.72),0 0 42px rgba(201,168,76,.18),inset 0 1px 0 rgba(255,255,255,.05);
}

.mission-window-topbar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:1rem;
  padding:1rem 1.18rem .92rem;
  border-bottom:1px solid rgba(201,168,76,.18);
  background:linear-gradient(180deg,rgba(201,168,76,.09),rgba(0,0,0,.08));
}

.mission-window-kicker{
  font-family:'Cinzel',serif;
  font-size:.56rem;
  letter-spacing:.28em;
  color:#7fbfff;
  text-transform:uppercase;
  margin-bottom:.14rem;
}

.mission-window-actions{
  display:flex;
  align-items:center;
  gap:.5rem;
  flex-wrap:wrap;
  justify-content:flex-end;
}

.mission-window-status{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:.7rem;
  padding:.85rem 1rem;
  border-bottom:1px solid rgba(201,168,76,.12);
  background:rgba(0,0,0,.16);
}

.mission-status-tile{
  min-height:58px;
  padding:.62rem .78rem;
  border:1px solid rgba(232,196,82,.28);
  border-radius:8px;
  background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(0,0,0,.15));
}

.mission-status-tile span{
  display:block;
  font-family:'Cinzel',serif;
  font-size:.55rem;
  color:var(--dim);
  letter-spacing:.16em;
  text-transform:uppercase;
}

.mission-status-tile b{
  display:block;
  margin-top:.2rem;
  font-family:'Cinzel',serif;
  font-size:1.18rem;
  color:var(--gold);
}

.mission-window-content{
  padding:1rem;
  overflow:auto;
}

.mission-window-grid{
  grid-template-columns:minmax(0,1.05fr) minmax(320px,.95fr);
  gap:1rem;
  max-width:none;
}

#mission-control-window .mission-panel{
  border-radius:9px;
  border-color:rgba(232,196,82,.38);
  background:linear-gradient(180deg,rgba(8,10,16,.86),rgba(2,3,7,.92));
}

#mission-control-window .mission-panel-header{
  padding:.68rem .82rem;
}

#mission-control-window .mission-panel-icon{
