  align-items:center;
  justify-content:center;
  border:1px solid rgba(201,168,76,.24);
  border-radius:6px;
  color:#d9c27a;
  background:rgba(201,168,76,.07);
  font-family:'Cinzel',serif;
  font-size:.72rem;
}

#mission-control-window .mission-panel-svg,
#mission-control-window .dc-all-missions-svg{
  display:block!important;
  width:17px!important;
  height:17px!important;
  fill:none!important;
  color:currentColor!important;
  stroke:currentColor!important;
  stroke-width:1.9!important;
  stroke-linecap:round!important;
  stroke-linejoin:round!important;
  overflow:visible!important;
}

#mission-control-window .dc-all-missions-svg{
  width:17px!important;
  height:17px!important;
  fill:currentColor!important;
  stroke:none!important;
}

#mission-control-window .mission-live-panel .mission-panel-icon{
  position:relative!important;
  font-size:0!important;
}

#mission-control-window .mission-live-panel .mission-panel-icon::before,
#mission-control-window .mission-live-panel .mission-panel-icon::after{
  content:''!important;
  position:absolute!important;
  left:50%!important;
  top:50%!important;
