  will-change:opacity!important;
  contain:layout style paint!important;
}

html body .effect-blocked-flash .ebf-inner{
  color:#ff4b4b!important;
  text-shadow:0 3px 10px rgba(0,0,0,.9)!important;
  animation:blockedPopLite 1.25s ease-out forwards!important;
  will-change:transform,opacity!important;
}

html body #last-turn-banner{
  background:transparent!important;
  animation:lastTurnInLite .32s ease-out forwards!important;
  will-change:opacity!important;
  contain:layout style paint!important;
}

html body #last-turn-banner > div{
  color:#ff4b4b!important;
  text-shadow:0 3px 10px rgba(0,0,0,.9)!important;
  animation:lastTurnPulseLite 1.15s ease-out forwards!important;
  will-change:transform,opacity!important;
}

@keyframes blockedFlashLite{
  0%{opacity:0;}
  14%{opacity:1;}
  78%{opacity:1;}
  100%{opacity:0;}
}

@keyframes blockedPopLite{
  0%{transform:translateY(8px) scale(.94);opacity:0;}
  18%{transform:translateY(0) scale(1);opacity:1;}
  78%{transform:translateY(0) scale(1);opacity:1;}
  100%{transform:translateY(-6px) scale(.98);opacity:0;}
}

@keyframes lastTurnInLite{
  from{opacity:0;}
  to{opacity:1;}
}

@keyframes lastTurnPulseLite{
  0%{transform:translateY(8px) scale(.96);opacity:0;}
  18%{transform:translateY(0) scale(1);opacity:1;}
  100%{transform:translateY(0) scale(1);opacity:1;}
}

