}

@keyframes cardflyLite{
  0%{opacity:.92;transform:translate3d(0,0,0) scale(.92) rotate(-2deg);}
  72%{opacity:1;transform:translate3d(var(--dx),calc(var(--dy) - 8px),0) scale(.86) rotate(1deg);}
  100%{opacity:0;transform:translate3d(var(--dx),var(--dy),0) scale(.78) rotate(0);}
}

@keyframes drawLitePulse{
