  background:
    linear-gradient(180deg,rgba(18,22,34,.9),rgba(6,8,15,.84) 62%,rgba(2,4,9,.9));
  box-shadow:
    inset 0 0 0 1px rgba(255,246,191,.03),
    0 1px 0 rgba(255,246,191,.06);
  box-sizing:border-box;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:.38rem;
  overflow:hidden;
  position:relative;
  contain:layout style paint;
  text-align:center;
}

#s-game .landscape-panel::before,
#s-game .landscape-panel::after{
  content:'';
  position:absolute;
  pointer-events:none;
}

#s-game .landscape-panel::before{
  inset:9px;
  border:1.5px solid rgba(111,91,38,.72);
  border-radius:3px;
  background:none;
  opacity:.94;
}

#s-game .landscape-panel::after{
  inset:15px;
  border-radius:2px;
  background:
    linear-gradient(90deg,rgba(111,91,38,.72),rgba(111,91,38,.72)) left top/15px 1.5px no-repeat,
    linear-gradient(180deg,rgba(111,91,38,.72),rgba(111,91,38,.72)) left top/1.5px 15px no-repeat,
    linear-gradient(90deg,rgba(111,91,38,.72),rgba(111,91,38,.72)) right bottom/15px 1.5px no-repeat,
    linear-gradient(180deg,rgba(111,91,38,.72),rgba(111,91,38,.72)) right bottom/1.5px 15px no-repeat;
  opacity:.94;
}

#s-game .landscape-panel > *{
  position:relative;
  z-index:1;
}

#s-game .landscape-panel.empty{opacity:.45;}

#s-game .landscape-kicker{
