  display:none!important;
  width:0!important;
  height:0!important;
}

/* The title screen already provides a dark background beneath this nearly
   opaque window. Re-blurring that full screen on every background frame was
   the main Public Decks FPS cost. Contain the four-card page as one paint
   surface and avoid decorative compositor layers inside it. */
html body #modal.public-decks-performance-layer{
  background:
    linear-gradient(180deg,rgba(5,7,12,.70),rgba(5,7,12,.84)),
    url('../../optimized/backgrounds/titlscreenbackgrounds_bg1.jpg?v=bg20260510d') center/cover no-repeat!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}
html body #modal.public-decks-performance-layer .modal.public-decks-hub-modal,
html body #modal.public-decks-performance-layer .pd-library-v3{
  filter:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}
html body #modal.public-decks-performance-layer .modal.public-decks-hub-modal{
  background:linear-gradient(145deg,rgba(9,17,27,.94),rgba(3,8,15,.97) 72%)!important;
}
html body #modal.public-decks-performance-layer .pd-library-v3{
  contain:layout paint style!important;
  isolation:isolate!important;
}
html body #modal.public-decks-performance-layer .pd-library-v3 :is(.pdx-card,.pdx-art,.pdx-info,.pdx-actions,.pdx-rank){
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  will-change:auto!important;
}

/* Freeze the obscured title scene while the Public Decks hub is open. Its
   ambient filters/animations cannot be seen through the opaque library, but
   previously continued consuming a full compositor pass behind every card. */
html body.public-decks-performance-active #s-title :is(.screen-bg,.title-overlay,.title-content,.title-profile,.daily-challenges-panel){
  animation-play-state:paused!important;
}
/* The hub is its own full-screen opaque surface. Do not keep the title scene
   in the paint/compositor tree behind it; hiding it is restored automatically
   when closePublicDecks removes the body class. */
html body.public-decks-performance-active #s-title{
  visibility:hidden!important;
  content-visibility:hidden!important;
  pointer-events:none!important;
}
html body.public-decks-performance-active #s-title *,
html body.public-decks-performance-active #s-title::before,
html body.public-decks-performance-active #s-title::after{
  animation:none!important;
  transition:none!important;
}
html body.public-decks-performance-active #s-title :is(.title-content,.title-profile,.daily-challenges-panel){
  pointer-events:none!important;
}
html body #modal.public-decks-performance-layer .pd-library-v3 :is(.pd-v3-header,.pd-v3-toolbar,.pdx-card,.pdx-art,.pdx-info,.pdx-actions,.pdx-stats > span){
  filter:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  box-shadow:none!important;
}
html body #modal.public-decks-performance-layer .pd-library-v3 .pd-v3-close{
  position:relative!important;
  z-index:50!important;
  pointer-events:auto!important;
  touch-action:manipulation!important;
}

