/* Large zone-total reduction feedback, synchronized with zone-debuff overlays. */
html body .zone-fate-loss-burst{
  position:fixed;
  z-index:100120;
  pointer-events:none;
  transform:translate(-50%,-35%) scale(.72);
  opacity:0;
  color:#ff9a91;
  font-family:var(--serif,Georgia,serif);
  font-size:clamp(34px,3.25vw,58px);
  font-weight:800;
  line-height:1;
  letter-spacing:-.045em;
  text-shadow:0 0 5px rgba(255,96,82,.95),0 0 18px rgba(228,49,45,.78),0 3px 0 rgba(40,5,8,.9);
  will-change:transform,opacity,filter;
}
html body .zone-fate-loss-burst.show{animation:fate-zone-loss-burst 1.4s cubic-bezier(.16,.82,.2,1) both;}
@keyframes fate-zone-loss-burst{
  0%{opacity:0;transform:translate(-50%,-15%) scale(.62);filter:blur(3px);}
  14%{opacity:1;transform:translate(-50%,-62%) scale(1.18);filter:blur(0);}
  62%{opacity:1;transform:translate(-50%,-112%) scale(1);filter:blur(0);}
  100%{opacity:0;transform:translate(-50%,-175%) scale(.9);filter:blur(1px);}
}
html.fate-animations-off body .zone-fate-loss-burst.show{animation-duration:.36s;}

