/* Persistent low-Morale supporter expiry state. The final icon treatment can
   replace this coded placeholder without changing the shared timer logic. */
.bc.fate-low-morale-expiry {
  isolation: isolate;
}

.bc .bc-low-morale-expiry {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: inherit;
  color: #ff9b9f;
  background: radial-gradient(circle at 50% 48%, rgba(111, 8, 24, .22), transparent 64%);
  box-shadow: inset 0 0 15px rgba(235, 47, 75, .16);
  text-shadow: 0 0 9px rgba(255, 49, 77, .94), 0 2px 3px #160207;
  pointer-events: none;
  animation: fate-low-morale-supporter-pulse 2.8s ease-in-out infinite;
}

.bc .bc-low-morale-heart {
  position:relative;
  display:block;
  font:900 clamp(28px,3.2vw,52px)/1 Georgia,serif;
  transform:scaleX(1.08);
}
.bc .bc-low-morale-heart::after{
  content:"";
  position:absolute;
  left:50%;top:4%;width:3px;height:92%;
  background:#ffe8e4;
  clip-path:polygon(35% 0,100% 0,58% 35%,100% 53%,46% 100%,0 100%,38% 56%,0 36%);
  transform:translateX(-50%) rotate(8deg);
  filter:drop-shadow(0 0 2px #ff334f);
}

.cd-low-morale-expiry {
  display: inline-flex;
  align-items:center;
  gap: 4px;
  margin: 0 0 0 8px;
  padding: 4px 7px;
  border: 1px solid rgba(220, 74, 78, .58);
  border-radius: 999px;
  color: rgba(255, 235, 231, .86);
  background: rgba(82, 10, 20, .22);
  vertical-align:middle;
  white-space:nowrap;
  flex:0 0 auto;
}
.cd-low-morale-heart{color:#ff6f79;font:900 1.15rem/1 Georgia,serif;text-shadow:0 0 7px rgba(255,61,82,.82);transform:scaleX(1.08)}

.cd-low-morale-expiry-label {
  color: #ff8d8d;
  font: 800 .54rem/1 Cinzel, serif;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.cd-low-morale-expiry strong {
  color: #ffe1d9;
  font: 700 .52rem/1 Cinzel, serif;
}

@keyframes fate-low-morale-supporter-pulse {
  0%, 100% { opacity: .5; filter: saturate(.82); }
  50% { opacity: 1; filter: saturate(1.18); }
}

/* Zoe's INTJ Stare: softly project the square's eye sigil over a trapped card. */
.bc.fate-zoe-field-lock { isolation: isolate; }
.bc .bc-zoe-field-lock {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  border-radius: inherit;
  color: #ead8ff;
  background: radial-gradient(circle at 50% 50%, rgba(94, 54, 150, .18), transparent 68%);
  box-shadow: inset 0 0 16px rgba(153, 95, 216, .16);
  pointer-events: none;
  animation: fate-zoe-field-lock-pulse 2.8s ease-in-out infinite;
}
.bc .bc-zoe-field-lock-icon {
  display: block;
  width: 68%;
  height: 68%;
  filter: drop-shadow(0 0 7px rgba(174, 116, 237, .72));
}
.bc .bc-zoe-field-lock-icon svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
@keyframes fate-zoe-field-lock-pulse {
  0%, 100% { opacity: .38; filter: saturate(.82); }
  50% { opacity: .82; filter: saturate(1.14); }
}
